// C# — Binary Search (Iterative)
int[] arr = { 5, 12, 23, 37, 45, 56, 70, 89, 95 };
int target = 95;

int left = 0;
int right = arr.Length - 1;

while (left <= right)
{
    int mid = left + (right - left) / 2;

    if (arr[mid] == target)
    {
        return mid; // Found at index 8
    }
    else if (arr[mid] < target)
    {
        left = mid + 1;
    }
    else
    {
        right = mid - 1;
    }
}

// C++ — Binary Search (Iterative)
#include <iostream>
using namespace std;

int main() {
    int arr[] = {5, 12, 23, 37, 45, 56, 70, 89, 95};
    int target = 95;
    int left = 0, right = 8;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (arr[mid] == target) {
            return mid; // Found at 8
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

// Java — Binary Search (Iterative)
public class BinarySearch {
    public static int search(int[] arr, int target) {
        int left = 0, right = arr.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] == target) return mid;
            if (arr[mid] < target) left = mid + 1;
            else right = mid - 1;
        }
        return -1;
    }
}

// JavaScript — Binary Search (Iterative)
function binarySearch(arr, target) {
    let left = 0, right = arr.length - 1;
    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        if (arr[mid] === target) return mid;
        if (arr[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}
